// One message per run: which keywords' SERP layout actually moved.
const rows = $input.all().map((item) => item.json);

// Kept in sync with the threshold used in Record SERP Result — SERP layout changes are gross
// (an ad block, an AI answer box, a local pack), so ~10% is the band, not `> 0`.
const SHIFT_THRESHOLD = 10;

const shifted = rows
  .filter((r) => r.status === 'shifted')
  .sort((a, b) => Number(b.mismatchPercentage) - Number(a.mismatchPercentage));
const stable = rows.filter((r) => r.status === 'stable');
const failed = rows.filter((r) => r.status === 'failed');

const label = (r) =>
  `${r.keyword || r.url}${r.country ? ` [${String(r.country).toUpperCase()}]` : ''}`;

const lines = [];
lines.push(
  `*Daily SERP layout digest* — ${shifted.length} shifted · ${stable.length} stable · ${failed.length} failed (${rows.length} keywords checked, shift threshold ${SHIFT_THRESHOLD}%)`
);

if (shifted.length) {
  lines.push('');
  lines.push('*SERP layout shifted* (largest change first)');
  for (const r of shifted) {
    // Raw mismatchPercentage on purpose — toFixed(1) renders a real 0.01% change as "0.0%".
    const diff = r.diffLink ? ` · <${r.diffLink}|view diff>` : '';
    lines.push(`• <${r.url}|${label(r)}> — ${r.mismatchPercentage}%${diff}`);
  }
}

if (failed.length) {
  lines.push('');
  lines.push('*Could not be captured or compared*');
  for (const r of failed) {
    lines.push(`• ${label(r)} — ${r.message || 'unknown error'}`);
  }
  lines.push(
    '_Search engines bot-gate automated requests: a consent wall or CAPTCHA page is the most likely cause._'
  );
}

if (!shifted.length && !failed.length) {
  lines.push('');
  lines.push(`✅ No SERP moved more than ${SHIFT_THRESHOLD}% since its baseline.`);
}

return [
  {
    json: {
      digest: lines.join('\n'),
      shiftedCount: shifted.length,
      stableCount: stable.length,
      failedCount: failed.length,
      totalCount: rows.length,
    },
  },
];
